set-variable.value:
@{
      var authorization = context.Request.Headers.GetValueOrDefault("Authorization", "");
      var jwtValidated = context.Variables.GetValueOrDefault<bool>("callerJwtValidated", false);
      if (jwtValidated && !string.IsNullOrEmpty(authorization) && authorization.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase))
      {
          try
          {
              var token = authorization.Substring(7);
              var parts = token.Split('.');
              if (parts.Length >= 2)
              {
                  var base64 = parts[1].Replace('-', '+').Replace('_', '/');
                  var padded = base64.PadRight(base64.Length + (4 - base64.Length % 4) % 4, '=');
                  var payload = System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(padded));
                  var json = Newtonsoft.Json.Linq.JObject.Parse(payload);
                  var appId = json["appid"]?.ToString() ?? json["azp"]?.ToString();
                  if (!string.IsNullOrEmpty(appId))
                  {
                      return appId;
                  }
              }
          }
          catch
          {
          }
      }

      return context.Subscription?.Id ?? "unknown";
  }
